/*
 * dir_$old_reclaim_block - evict a block of plain entries from some other
 * hash chain and hand it out again
 *
 * Original address: 0x00E54E62
 * Size: 294 bytes (0x00E54E62 .. 0x00E54F89)
 * Generated by: Claude Opus 5.5
 *
 * Module-local routine of the OLD_DIR segment (no map symbol; Ghidra had it
 * as FUN_00e54e62).  Callers: dir_$old_find_overflow_slot (0x00E5511E) and
 * dir_$old_add_link_entry (0x00E5549E, 0x00E5550A), each only in replace
 * mode and only once dir_$old_alloc_block has come back empty.
 *
 * Frame: (0x8,A6) handle (A2, the mapped directory), (0xC,A6) hash word
 * (D0 -> D4).  Result in D0w.  A6-0x10 is the "evictable" boolean.
 *
 * Blocks:
 *   0x00E54E74-0x00E54E80  no buckets (+0x2 == 0): return at once
 *   0x00E54E84-0x00E54E9C  once per bucket (dbf D5): hash = (hash + 1) mod
 *                          buckets through M$OIU$WLW
 *   0x00E54E9E-0x00E54EC8  an empty chain -> next bucket; else walk to the
 *                          chain's last block (+0x36A == 0)
 *   0x00E54ECC-0x00E54F12  from the last block back towards the head
 *                          (+0x36C): the block is evictable when every
 *                          used slot is type 1 without the no-evict bit
 *                          (bit 7 of slot byte +0x24); the first other slot stops
 *                          the scan
 *   0x00E54F18-0x00E54F5C  evictable: dir_$old_delete_entry(handle, block,
 *                          j, hash) for every used slot j
 *   0x00E54F60-0x00E54F66  and return dir_$old_alloc_block(handle) (the
 *                          emptied block went back on the free list)
 *   0x00E54F68-0x00E54F7C  not evictable: previous block, then next bucket
 *
 * Quirk reproduced: the Pascal function result is only assigned on the
 * eviction path.  Otherwise the caller gets whatever D0 last held and
 * treats a non-zero word as a block number: the hash argument when there
 * are no buckets, else what the last bucket left there - the bucket number
 * when its chain was empty, or the low word of `mulu.w #0x96' of the chain
 * head (the last block examined, 0x00E54F68).  `d0' tracks that register.
 */

#include "dir/dir_internal.h"
#include "math/math.h"

uint16_t dir_$old_reclaim_block(uint32_t handle, uint16_t hash)
{
    uint8_t *dir = (uint8_t *)ARCH_VA_TO_PTR(handle);  /* A2 */
    uint16_t d0 = hash;                                /* D0w */
    uint16_t h = hash;                                 /* D4 */
    uint16_t block;                                    /* D3 */
    uint16_t slots;
    uint16_t j;                                        /* D5 */
    int16_t n;                                         /* D5 (outer) */
    int16_t m;                                         /* D2 / D6 */
    int8_t evictable;                                  /* A6-0x10 */
    dir_$old_slot_t *slot;

    /* 0x00E54E74-0x00E54E80 */
    if (DIR_OLD_W(dir, DIR_OLD_HDR_BUCKETS) == 0) {
        return d0;
    }
    n = (int16_t)(DIR_OLD_W(dir, DIR_OLD_HDR_BUCKETS) - 1);

    do {
        /* 0x00E54E84-0x00E54E9C */
        h = (uint16_t)M$OIU$WLW((long)((uint32_t)h + 1),
                                (short)DIR_OLD_W(dir, DIR_OLD_HDR_BUCKETS));
        d0 = h;

        /* 0x00E54E9E-0x00E54EC8 */
        block = DIR_OLD_HASH_HEAD(dir, h);
        if (block == 0) {
            continue;
        }
        while (DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_NEXT) != 0) {
            block = DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_NEXT);
        }

        while (block != 0) {
            /* 0x00E54ECC-0x00E54F12 */
            evictable = (int8_t)0xFF;
            slots = DIR_OLD_W(dir, DIR_OLD_HDR_BLOCK_SLOTS);
            if (slots != 0) {
                m = (int16_t)(slots - 1);
                j = 1;
                do {                                    /* dbf D2w */
                    slot = DIR_OLD_BLOCK_SLOT(dir, block, j);
                    if (slot->type != 0 &&
                        ((((uint8_t *)slot)[DIR_OLD_SLOT_FLAGS] & DIR_OLD_SLOT_NO_EVICT) != 0 ||
                         slot->type != DIR_OLD_SLOT_IN_USE)) {
                        evictable = 0;
                        break;
                    }
                    j++;
                } while (m-- != 0);
            }

            if (evictable < 0) {
                /* 0x00E54F18-0x00E54F5C */
                if (slots != 0) {
                    m = (int16_t)(slots - 1);
                    j = 1;
                    do {                                /* dbf D6w */
                        slot = DIR_OLD_BLOCK_SLOT(dir, block, j);
                        if (slot->type != 0) {
                            dir_$old_delete_entry(handle, block, j, h);
                        }
                        j++;
                    } while (m-- != 0);
                }
                /* 0x00E54F60-0x00E54F66 */
                return dir_$old_alloc_block(handle);
            }

            /* 0x00E54F68-0x00E54F72 */
            d0 = (uint16_t)((uint32_t)block * DIR_OLD_BLOCK_STRIDE);
            block = DIR_OLD_W(DIR_OLD_BLOCK(dir, block), DIR_OLD_BLOCK_PREV);
        }
    } while (n-- != 0);                                 /* dbf D5w */

    return d0;
}
